import numpy as np

def relu(x):
    return np.maximum(0, x)

def sigmoid(x):
    return 1 / (1 + np.exp(-x))

signals = np.array([-4.0, -1.0, 0.0, 1.0, 4.0])
print("Raw Signals:", signals)
print("ReLU (turns negative signals to 0):", relu(signals))
print("Sigmoid (squashes into [0, 1] probability):", np.round(sigmoid(signals), 3))

